INSERT INTO sections (slug, name_ja, sort_order) VALUES ('structure', 'Structure and Written Expression', 1) ON CONFLICT(slug) DO NOTHING;
INSERT INTO sections (slug, name_ja, sort_order) VALUES ('reading', 'Reading', 2) ON CONFLICT(slug) DO NOTHING;
INSERT INTO sections (slug, name_ja, sort_order) VALUES ('listening', 'Listening', 3) ON CONFLICT(slug) DO NOTHING;
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-horse', 'reading', 'The Domestication of the Horse', 'Archaeologists have long debated when and where humans first domesticated the horse. For much of the twentieth century, the prevailing view held that horse domestication began on the Eurasian steppe, in what is now Kazakhstan, roughly six thousand years ago. This theory rested largely on indirect evidence: wear patterns on horse teeth suggested the use of bits, and unusually large deposits of horse bones at certain sites hinted at organized herding rather than opportunistic hunting.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-coral', 'reading', 'Coral Bleaching', 'Coral reefs, though they occupy less than one percent of the ocean floor, support roughly a quarter of all known marine species. This extraordinary productivity depends on a partnership between coral polyps, tiny animals related to sea anemones, and microscopic algae called zooxanthellae that live within the polyps'' tissues. The algae photosynthesize and supply the coral with nutrients, while the coral provides the algae with a protected habitat and compounds needed for photosynthesis. It is the pigments within these algae that give healthy reefs their vivid colors.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-insulin', 'reading', 'The Discovery of Insulin', 'Before the 1920s, a diagnosis of type 1 diabetes was effectively a death sentence, particularly for children, who often survived only a few years after symptoms appeared. The disease''s connection to the pancreas had been suspected since the 1880s, after researchers observed that dogs whose pancreases were surgically removed developed symptoms strikingly similar to diabetes. Yet decades of attempts to isolate the pancreatic substance responsible for regulating blood sugar had failed, largely because digestive enzymes in the pancreas broke down the substance before it could be extracted in usable form.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-urban-heat', 'reading', 'Urban Heat Islands', 'Cities are, on average, measurably warmer than the rural areas that surround them, a phenomenon known as the urban heat island effect. Temperature differences between a city center and its outskirts can exceed five degrees Celsius on a calm, clear evening, though the effect is generally smaller during the day and in windy or cloudy conditions. The primary cause is not a mystery: materials common in urban construction, such as asphalt and dark rooftops, absorb far more solar radiation during the day than natural vegetation does, then slowly release that stored heat after sunset.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-silk-road', 'reading', 'The Silk Road''s Economic Legacy', 'The term "Silk Road" evokes images of camel caravans carrying silk from China to the Mediterranean, but the network of overland and maritime routes it describes carried far more than a single luxury good, and served a much wider economic function than simple long-distance trade. Spices, precious stones, glassware, paper-making technology, and even certain crops traveled these routes in both directions over roughly fifteen centuries, from around 130 BCE until the network''s decline in the fifteenth century following the rise of direct sea trade between Europe and Asia.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-impressionism', 'reading', 'The Rise of Impressionist Painting', 'In 1874, a group of Paris-based artists, denied entry into the officially sanctioned Salon exhibition, organized an independent show of their own work. Critics were largely unkind: one, mocking a Claude Monet painting titled "Impression, Sunrise", coined the term "Impressionist" as an insult, suggesting the works looked unfinished, as if the artists had captured only a fleeting impression rather than a fully realized scene. The label, intended to dismiss the movement, was instead adopted by the artists themselves.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-photosynthesis', 'reading', 'C4 Photosynthesis and Heat Tolerance', 'Most plants rely on a photosynthetic pathway known as C3 photosynthesis, in which the enzyme RuBisCO fixes carbon dioxide directly into a three-carbon compound. This pathway works efficiently under moderate temperatures, but in hot, dry conditions, RuBisCO increasingly binds oxygen instead of carbon dioxide, a wasteful side reaction called photorespiration that reduces the energy available for growth.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-bronze-age', 'reading', 'The Bronze Age Collapse', 'Around 1200 BCE, a number of powerful civilizations across the eastern Mediterranean and Near East, including the Hittite Empire, Mycenaean Greece, and numerous city-states along the Levantine coast, experienced a rapid and largely simultaneous decline within the span of a few decades. Major palace complexes were destroyed or abandoned, long-distance trade networks that had connected these societies collapsed, and writing systems used for administrative record-keeping disappeared in several regions for centuries afterward.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-loss-aversion', 'reading', 'Loss Aversion in Behavioral Economics', 'Classical economic theory long assumed that people evaluate financial decisions rationally, weighing potential gains and losses of equal size as equivalent in importance. Research in behavioral economics, however, has repeatedly shown that this assumption does not match how people actually behave. In a series of experiments beginning in the late 1970s, psychologists Daniel Kahneman and Amos Tversky demonstrated that people tend to feel the pain of a loss roughly twice as intensely as the pleasure of an equivalent gain, a pattern they termed loss aversion.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-plate-tectonics', 'reading', 'From Continental Drift to Plate Tectonics', 'In 1912, the German meteorologist Alfred Wegener proposed that the continents had once been joined together in a single landmass, which he called Pangaea, before gradually drifting apart to their current positions. As evidence, he pointed to the way the coastlines of South America and Africa appeared to fit together like puzzle pieces, as well as matching rock formations and fossils of the same land-dwelling species found on continents now separated by vast oceans.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-printing-press', 'reading', 'The Printing Press and the Spread of Knowledge', 'Around 1450, the German goldsmith Johannes Gutenberg introduced a printing system in Europe that combined movable metal type, an oil-based ink suited to metal surfaces, and a modified wine press to apply even pressure to paper. While woodblock printing and even earlier forms of movable type had existed in East Asia for centuries, Gutenberg''s particular combination of technologies proved remarkably well suited to the alphabetic scripts used in Europe, since a relatively small set of reusable letter molds could be rearranged to print any text.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-octopus', 'reading', 'Octopus Cognition and Camouflage', 'Octopuses possess a nervous system strikingly different from that of most intelligent animals studied by scientists. Rather than concentrating most neurons in a central brain, roughly two-thirds of an octopus''s several hundred million neurons are distributed throughout its eight arms, allowing each arm to process sensory information and coordinate movement with a surprising degree of independence from the central brain. This distributed architecture has led some researchers to describe octopus cognition as fundamentally different from the centralized intelligence found in vertebrates.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-dust-bowl', 'reading', 'The Dust Bowl of the 1930s', 'During the 1930s, a series of severe dust storms struck the southern Great Plains region of the United States, an area encompassing parts of Texas, Oklahoma, Kansas, Colorado, and New Mexico that came to be known as the Dust Bowl. The storms stripped away millions of tons of topsoil, occasionally carrying dust as far as cities on the East Coast and darkening skies hundreds of miles from their point of origin.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-renaissance-patronage', 'reading', 'The Renaissance Patronage System', 'During the Italian Renaissance, artists rarely worked as independent creators producing pieces for open sale, as is common today. Instead, most operated within a patronage system, in which wealthy individuals, religious institutions, or civic governments commissioned specific works and paid for materials, labor, and often the artist''s living expenses over the course of a project. A patron''s commission typically specified not only the general subject matter but sometimes exact dimensions, materials such as expensive pigments like ultramarine, and even the number of figures to be included.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-bird-navigation', 'reading', 'How Migratory Birds Navigate', 'Every year, many species of birds travel thousands of kilometers between breeding and wintering grounds, often returning to the same nesting site with remarkable precision despite having no apparent way to consult a map. For decades, researchers have investigated how migratory birds manage to navigate over such vast distances, and the current consensus is that birds rely not on a single method but on multiple, overlapping navigational systems.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-assembly-line', 'reading', 'The Invention of the Assembly Line', 'In 1913, Henry Ford''s automobile company introduced a moving assembly line at its Highland Park, Michigan plant, fundamentally changing how manufactured goods were produced. Before this innovation, workers building a Ford automobile moved from station to station, carrying components and assembling entire vehicles largely by hand, a process that could take more than twelve hours per car. Ford''s engineers instead arranged production so that a partially built car moved past stationary workers on a conveyor system, each of whom repeated a single specialized task as the vehicle passed.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-permafrost', 'reading', 'Permafrost Thaw and Methane Release', 'Permafrost is soil, rock, or sediment that has remained frozen for at least two consecutive years, and in many parts of the Arctic it has stayed frozen for thousands of years. It underlies roughly a quarter of the exposed land in the Northern Hemisphere, spanning large areas of Siberia, Alaska, and northern Canada. Trapped within this frozen ground is an enormous reserve of ancient plant and animal material that never fully decomposed because cold temperatures prevented the microorganisms responsible for decay from functioning.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-hammurabi', 'reading', 'The Code of Hammurabi', 'Around 1754 BCE, Hammurabi, the sixth king of the Babylonian dynasty, had a set of laws carved onto a nearly eight-foot stone pillar, or stele, and displayed publicly in the city of Babylon. Though earlier Mesopotamian rulers had issued legal proclamations, Hammurabi''s code stands out for its scope and its ambition to present a unified, systematic body of law covering matters from commerce and property to family disputes and criminal punishment.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-lichen', 'reading', 'Symbiosis in Lichen', 'A lichen is not a single organism but a stable partnership between at least two very different kinds of life: a fungus and a photosynthetic partner, usually a species of algae or, in some cases, a cyanobacterium. Roughly twenty thousand species of lichen have been described, and they grow in an extraordinarily wide range of environments, from tropical rainforests to bare Arctic rock, tree bark, and even the surfaces of gravestones.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-vaccination', 'reading', 'Edward Jenner and the Origins of Vaccination', 'By the late eighteenth century, smallpox killed an estimated ten percent of the population in some European countries during major outbreaks, and it left many survivors permanently scarred or blind. Physicians had long practiced variolation, a risky method of deliberately exposing healthy people to material from smallpox sores to induce a milder case of the disease, but variolation itself sometimes caused fatal infections and could spread the disease further. Rural folklore, meanwhile, held that milkmaids who had previously caught cowpox, a much milder disease affecting cattle, rarely contracted smallpox at all.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-industrial-urbanization', 'reading', 'Urbanization During the Industrial Revolution', 'Before the Industrial Revolution, most people in Britain lived in small rural villages and made their living from agriculture or small-scale craft production. The introduction of mechanized textile manufacturing and the growing use of steam power in the late eighteenth and early nineteenth centuries changed this pattern dramatically, as factories requiring large numbers of workers and steady access to coal and transportation networks tended to concentrate in and around a small number of towns. Manchester, for example, grew from a modest market town of about twenty-five thousand people in 1770 to a city of several hundred thousand within a few decades.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-echolocation', 'reading', 'Echolocation in Bats', 'Most bat species navigate and hunt not primarily by sight but by echolocation, a biological sonar system in which the animal emits high-frequency sound pulses, often well above the range of human hearing, and interprets the echoes that bounce back from objects in the environment. By analyzing tiny differences in the timing, intensity, and frequency of these returning echoes, a bat can determine not just the distance and direction of an object but also, with remarkable precision, its size, shape, texture, and even whether it is moving.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-panama-canal', 'reading', 'The Construction of the Panama Canal', 'French engineers, led by Ferdinand de Lesseps, who had earlier overseen construction of the Suez Canal, began work on a canal across the Isthmus of Panama in 1881, attempting to build a sea-level waterway similar to the one at Suez. The project collapsed within a decade, defeated by a combination of financial mismanagement, unstable mountainous terrain, and, most devastatingly, disease: malaria and yellow fever killed an estimated twenty thousand workers, since the connection between these diseases and mosquitoes was not yet understood.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-cognitive-dissonance', 'reading', 'Cognitive Dissonance Theory', 'In the 1950s, psychologist Leon Festinger proposed that people experience a distinctly uncomfortable mental state, which he termed cognitive dissonance, whenever they simultaneously hold two beliefs, or a belief and a behavior, that contradict one another. According to Festinger, this discomfort is not merely unpleasant but actively motivating: people are driven to reduce the inconsistency, often without being fully aware they are doing so.
INSERT INTO passages (id, section_slug, title, body) VALUES ('p-desert-adaptations', 'reading', 'Adaptations to Desert Ecosystems', 'Deserts are defined not by heat alone but by extreme scarcity of precipitation, typically receiving less than 250 millimeters of rain per year, combined with dramatic swings in temperature between day and night due to the absence of moisture and cloud cover that would otherwise moderate the climate. Organisms that live in deserts must therefore cope with two related challenges simultaneously: severe water scarcity and thermal extremes that can range from scorching daytime heat to near-freezing nighttime cold.
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c01', 'structure', NULL, 'structure_completion', '_____ the mission was originally scheduled for launch in March, technical problems delayed it until June.', '["Although","Despite","Because of","In spite"]', 0, 'A dependent clause follows, so a subordinating conjunction like "Although" is required. "Despite" and "In spite (of)" take noun phrases, not clauses, and "Because of" would reverse the intended meaning.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c02', 'structure', NULL, 'structure_completion', 'Not until the twentieth century _____ widely available to ordinary households.', '["electricity became","did electricity become","electricity did become","had electricity become"]', 1, '"Not until..." at the start of a sentence triggers subject-auxiliary inversion: did + subject + base verb.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c03', 'structure', NULL, 'structure_completion', 'The committee requested that the report _____ before the end of the fiscal year.', '["is submitted","submitted","be submitted","will be submitted"]', 2, '"Request that" triggers the subjunctive mood: the base form "be submitted" is used regardless of tense.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c04', 'structure', NULL, 'structure_completion', '_____ of the two candidates has the experience necessary to lead the department.', '["Neither","None","Both","All"]', 0, '"Neither" is used for exactly two items; "none" is reserved for three or more.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c05', 'structure', NULL, 'structure_completion', 'The museum''s new wing, _____ construction took nearly three years, opens to the public next month.', '["which","whose","that","who"]', 1, 'A possessive relative pronoun is needed to show that the construction belongs to the wing; "whose" fills that role for both people and things.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c06', 'structure', NULL, 'structure_completion', 'It is essential that every employee _____ the updated safety guidelines before returning to the factory floor.', '["reviews","review","reviewing","will review"]', 1, 'After "It is essential that," the subjunctive base form "review" is required.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c07', 'structure', NULL, 'structure_completion', '_____ increasing air travel, many small regional airports have struggled to remain profitable.', '["Despite","Although","However","Nevertheless"]', 0, 'A noun phrase ("increasing air travel") follows, so a preposition like "Despite" is needed rather than a conjunction or adverb.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c08', 'structure', NULL, 'structure_completion', 'The new bridge is _____ than the one it replaced, allowing much heavier trucks to cross safely.', '["more strong","stronger","as strong","the strongest"]', 1, 'A one-syllable adjective like "strong" forms its comparative by adding "-er," not with "more."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c09', 'structure', NULL, 'structure_completion', 'Rarely _____ such a well-preserved fossil found outside a controlled excavation site.', '["is","has been","it is","being"]', 1, 'The negative adverb "Rarely" at the start of the sentence requires inversion: has + subject + been.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c10', 'structure', NULL, 'structure_completion', 'The scientist explained _____ the experiment had failed.', '["why did","why","that why","the reason why did"]', 1, 'In an embedded (indirect) question, normal word order is used, not question-word inversion: "explained why the experiment had failed."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c11', 'structure', NULL, 'structure_completion', '_____ to reduce costs, the airline eliminated several unprofitable routes.', '["In an effort","With an effort","By effort","For efforts"]', 0, '"In an effort to + verb" is the standard fixed expression meaning "in order to."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c12', 'structure', NULL, 'structure_completion', 'The data collected during the survey _____ far more comprehensive than researchers had expected.', '["were","was","are","have been"]', 0, '"Data" is the plural form of "datum" and in formal, tested English takes a plural verb ("were"), even though it is often used informally as a mass noun.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c13', 'structure', NULL, 'structure_completion', 'If the bridge _____ properly maintained, the collapse could have been prevented.', '["was","were","had been","has been"]', 2, 'This is a third conditional describing an unreal past situation ("could have been prevented"), which requires "had been" in the if-clause.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c14', 'structure', NULL, 'structure_completion', 'Only after the results were independently verified _____ the findings for publication.', '["the team accepted","did the team accept","the team did accept","had the team accepted"]', 1, '"Only after..." at the start of a sentence triggers subject-auxiliary inversion in the main clause: did + subject + base verb.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c15', 'structure', NULL, 'structure_completion', 'The new regulation applies to _____ manufacturers importing goods into the country.', '["all","every","each","all of"]', 0, '"All" correctly modifies the plural noun "manufacturers"; "every" and "each" require a singular noun, and "all of" would need "the" before the noun.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c16', 'structure', NULL, 'structure_completion', 'The lecture covered not only the causes of the recession _____ also its long-term effects on employment.', '["but","and","or","so"]', 0, '"Not only... but also..." is the fixed correlative conjunction pair.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c17', 'structure', NULL, 'structure_completion', 'The professor recommended _____ the assignment before attending the seminar.', '["to complete","completing","complete","completion"]', 1, '"Recommend" is followed by a gerund ("completing"), not an infinitive.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c18', 'structure', NULL, 'structure_completion', '_____ the report is finished, the team will begin drafting the next proposal.', '["Until","Once","Unless","Since"]', 1, '"Once" correctly conveys "as soon as," matching the logical sequence of finishing the report and then starting the next task.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c19', 'structure', NULL, 'structure_completion', 'The findings of the two studies, though conducted independently, _____ remarkably similar.', '["is","was","are","has been"]', 2, 'The subject "findings" is plural, so the present-tense verb must be "are."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c20', 'structure', NULL, 'structure_completion', 'The city council debated whether the new stadium _____ funded through public bonds or private investment.', '["should be","should","should being","is should be"]', 0, 'The passive modal construction "should be funded" is required after "whether."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c21', 'structure', NULL, 'structure_completion', 'The committee has yet _____ a final decision on the merger.', '["to make","making","make","made"]', 0, '"Has yet to + base verb" is a fixed expression meaning "has not yet."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c22', 'structure', NULL, 'structure_completion', 'The more data scientists collected, _____ their models became.', '["more accurate","the more accurate","accurate","most accurate"]', 1, 'The correlative comparative structure "The more..., the more..." requires "the" before both comparatives.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c23', 'structure', NULL, 'structure_completion', 'The manuscript, along with the accompanying illustrations, _____ donated to the university library.', '["were","was","have been","are"]', 1, 'The phrase "along with the accompanying illustrations" is a parenthetical, so the verb agrees with the singular subject "manuscript": "was."', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c24', 'structure', NULL, 'structure_completion', 'Few of the witnesses _____ willing to testify in court.', '["was","is","were","has been"]', 2, '"Few" is a plural quantifier, so the verb must be plural: "were."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e01', 'structure', NULL, 'structure_error_id', 'The results of the study, which was published last year, suggest that the new treatment is more effective than previously believed.', '["which was published last year","suggest that the new treatment","is more effective than","previously believed"]', 0, 'The relative pronoun "which" refers to "results" (plural), so the verb should be "were," not "was."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e02', 'structure', NULL, 'structure_error_id', 'Despite their initial success, the company''s profits have steady declined over the past three years.', '["their initial success","the company''s profits","have steady declined","over the past three years"]', 2, 'The verb "declined" must be modified by an adverb, "steadily," not the adjective "steady."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e03', 'structure', NULL, 'structure_error_id', 'Each of the applicants were required to submit a portfolio along with a letter of recommendation.', '["were required to","submit a portfolio","along with","a letter of recommendation"]', 0, '"Each of the applicants" is grammatically singular, so the verb should be "was required," not "were required."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e04', 'structure', NULL, 'structure_error_id', 'The number of students enrolling in online courses have risen sharply since the university expanded its remote offerings.', '["enrolling in online courses","have risen sharply","since the university","expanded its remote offerings"]', 1, '"The number of" takes a singular verb ("has risen"), unlike "A number of," which takes a plural verb.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e05', 'structure', NULL, 'structure_error_id', 'Scientists have long debated whether Pluto should be classify as a planet or a dwarf planet.', '["whether Pluto should","be classify as","a planet or","a dwarf planet"]', 1, 'After the modal "should," the verb must appear in its base passive form: "be classified," not "be classify."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e06', 'structure', NULL, 'structure_error_id', 'The recipe calls for two cups of flour, a teaspoon of salt, and beating the eggs until frothy.', '["two cups of flour","a teaspoon of salt","beating the eggs","until frothy"]', 2, 'The list should maintain parallel noun-phrase structure ("two cups of flour," "a teaspoon of salt," "two beaten eggs"), but "beating the eggs" breaks the pattern by shifting to a gerund phrase.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e07', 'structure', NULL, 'structure_error_id', 'Although the medication reduced her symptoms, it also caused several side effect that concerned her doctor.', '["reduced her symptoms","it also caused","several side effect","that concerned her doctor"]', 2, 'The quantifier "several" requires a plural noun, so it should be "several side effects," not "several side effect."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e08', 'structure', NULL, 'structure_error_id', 'By the time the film crew arrived, the storm had already destroy much of the coastal village''s fishing fleet.', '["the storm had already","destroy much of","the coastal village''s","fishing fleet"]', 1, 'The past perfect tense requires "had already destroyed," using the past participle, not the base form "destroy."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e09', 'structure', NULL, 'structure_error_id', 'The findings, which was presented at the conference, challenged decades of prior research on the subject.', '["which was presented at the conference","challenged decades of","prior research","on the subject"]', 0, 'The relative pronoun "which" refers to "findings" (plural), so the verb should be "were," not "was."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e10', 'structure', NULL, 'structure_error_id', 'The engineers worked quick to repair the damaged pipeline before the storm arrived.', '["worked quick to repair","the damaged pipeline","before the storm","arrived"]', 0, 'The verb "worked" must be modified by the adverb "quickly," not the adjective "quick."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e11', 'structure', NULL, 'structure_error_id', 'The committee is responsible to ensure that all safety protocols are strictly followed during construction.', '["is responsible to ensure","that all safety protocols","are strictly followed","during construction"]', 0, 'The correct idiom is "responsible for ensuring," not "responsible to ensure."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e12', 'structure', NULL, 'structure_error_id', 'Of the two proposals, the second one is more preferable because it costs less to implement.', '["Of the two proposals","the second one is more preferable","because it costs less","to implement"]', 1, '"Preferable" already carries a comparative meaning ("more desirable"), so adding "more" is redundant; it should simply be "preferable."', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e13', 'structure', NULL, 'structure_error_id', 'By next year, the company will completed the transition to renewable energy sources.', '["By next year","the company will completed","the transition to","renewable energy sources"]', 1, '"By next year" signals an action completed before a future point in time, which requires the future perfect: "will have completed."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e14', 'structure', NULL, 'structure_error_id', 'The workshop taught participants how to write clearly, organize their arguments, and to present with confidence.', '["how to write clearly","organize their arguments","and to present","with confidence"]', 2, 'The list should maintain parallel structure ("write," "organize," "present"), but "to present" breaks the pattern by repeating "to."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e15', 'structure', NULL, 'structure_error_id', 'There has been several complaints filed against the company this month.', '["There has been","several complaints","filed against","the company this month"]', 0, 'The subject "complaints" is plural, so the existential construction requires "There have been," not "There has been."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e16', 'structure', NULL, 'structure_error_id', 'Fewer rainfall this year has led to a severe drought across the region.', '["Fewer rainfall this year","has led","to a severe drought","across the region"]', 0, '"Rainfall" is an uncountable noun, so it should be modified by "less," not "fewer," which is reserved for countable nouns.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c25', 'structure', NULL, 'structure_completion', 'The book _____ on the table belongs to my sister.', '["lying","lay","lied","is lying"]', 0, 'A reduced relative clause uses the present participle "lying" (from the intransitive verb "lie") to modify "book"; "lay" and "lied" are finite verb forms that do not fit a reduced relative clause here.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c26', 'structure', NULL, 'structure_completion', '_____ several times, the manuscript was finally accepted for publication.', '["Revising","Having revised","Revised","To revise"]', 2, 'Since the manuscript itself was revised rather than doing the revising, the passive past participle "Revised" is required, not the active forms "Revising" or "Having revised."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c27', 'structure', NULL, 'structure_completion', '_____ finished her research, she began writing the final report.', '["Having","Have","To have","Had"]', 0, '"Having + past participle" (the perfect participle) shows an action completed before the main clause''s action; "Have," "To have," and "Had" do not form this participial construction.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c28', 'structure', NULL, 'structure_completion', 'The new library _____ by the city council since 2019.', '["has been funded","is funding","funds","had funding"]', 0, 'The funding began in the past and continues into the present ("since 2019"), and the library receives the action, so the present perfect passive "has been funded" is correct.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c29', 'structure', NULL, 'structure_completion', 'The proposal _____ by the board before the end of the quarter.', '["will review","will be reviewed","reviews","is reviewing"]', 1, 'The proposal receives the action of reviewing, so the passive voice is required; "will be reviewed" correctly expresses the future passive.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c30', 'structure', NULL, 'structure_completion', 'If it _____ tomorrow, the outdoor ceremony will be moved indoors.', '["rains","will rain","rained","would rain"]', 0, 'In a first conditional describing a real future possibility, the if-clause uses the simple present ("rains"), while the main clause uses "will."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c31', 'structure', NULL, 'structure_completion', 'If the company _____ more resources into research, it would likely develop new products faster.', '["puts","put","will put","had put"]', 1, 'This second conditional describes a hypothetical present situation ("would likely develop"), which requires the simple past "put" in the if-clause.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c32', 'structure', NULL, 'structure_completion', 'The interviewer asked the candidate _____ she had chosen to leave her previous job.', '["why did","why","why had","that why"]', 1, 'In an embedded question, normal declarative word order is used, so "why she had chosen" is correct; question-word inversion ("why did she") is not used in indirect questions.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c33', 'structure', NULL, 'structure_completion', 'The city has invested _____ money in improving public transportation this year.', '["many","much","a number of","few"]', 1, '"Money" is an uncountable noun, so it should be modified by "much," not "many," "a number of," or "few," which are used with countable nouns.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c34', 'structure', NULL, 'structure_completion', '_____ effort went into designing the new bridge to withstand earthquakes.', '["A great deal of","A great number of","Many","Few"]', 0, '"Effort" is an uncountable noun, so "a great deal of" is the correct quantifier; "a great number of," "many," and "few" are used with countable nouns.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c35', 'structure', NULL, 'structure_completion', 'The meeting is scheduled _____ 3 p.m. on Thursday.', '["in","on","at","by"]', 2, 'The preposition "at" is used with specific clock times, such as "at 3 p.m."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c36', 'structure', NULL, 'structure_completion', 'The company''s headquarters are located _____ the corner of Fifth Avenue and Main Street.', '["in","at","on","by"]', 1, 'The idiom "at the corner of" is the standard way to describe a location at an intersection.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c37', 'structure', NULL, 'structure_completion', 'The committee''s decision was based _____ extensive research and community feedback.', '["in","on","at","for"]', 1, 'The correct collocation is "based on," meaning something is grounded in or derived from a source.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c38', 'structure', NULL, 'structure_completion', 'The professor''s argument consists _____ three main points, each supported by data.', '["of","in","with","from"]', 0, 'The correct collocation is "consist of," meaning to be composed of something.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c39', 'structure', NULL, 'structure_completion', 'The scientist reported that the results _____ significant implications for future research.', '["have","had","has","will have"]', 1, 'In reported speech with a past-tense reporting verb ("reported"), the tense typically shifts back, so "had" is used instead of the present "have."', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c40', 'structure', NULL, 'structure_completion', 'The evidence was _____ compelling that the jury reached a verdict within an hour.', '["so","such","too","very"]', 0, '"So + adjective + that" is the correct structure to show cause and result; "such" would require a noun phrase ("such compelling evidence").', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c41', 'structure', NULL, 'structure_completion', 'It was _____ a persuasive argument that even the skeptics were convinced.', '["so","such","too","very"]', 1, '"Such + a/an + adjective + noun + that" is the correct structure when a noun follows; "so" would be used without the article and noun ("so persuasive that").', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c42', 'structure', NULL, 'structure_completion', 'Before the factory closed, workers _____ commute over an hour each way.', '["use to","used to","are used to","get used to"]', 1, '"Used to + base verb" describes a repeated past habit that no longer occurs.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c43', 'structure', NULL, 'structure_completion', 'After years abroad, she _____ living in a different time zone from her family.', '["used to","use to","is used to","uses to"]', 2, '"Be used to + gerund/noun" means "to be accustomed to," which fits the context of an ongoing adjustment.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c44', 'structure', NULL, 'structure_completion', 'It took the new employees several weeks to _____ the company''s strict dress code.', '["use to","get used to","used to","be use to"]', 1, '"Get used to + gerund/noun" describes the process of becoming accustomed to something, which fits "took... several weeks."', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c45', 'structure', NULL, 'structure_completion', 'The homeowners decided to _____ the roof repaired before the rainy season began.', '["have","make","let","get to"]', 0, 'The causative structure "have something done" (have + object + past participle) means arranging for someone else to do the action.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c46', 'structure', NULL, 'structure_completion', 'The manager arranged to _____ the contract reviewed by the legal department before signing.', '["have get","get","make","let"]', 1, 'The causative structure "get something done" (get + object + past participle) is correct here; the other options do not fit this passive causative pattern.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c47', 'structure', NULL, 'structure_completion', '_____ patience is essential for anyone learning a new language.', '["The","A","An","(no article)"]', 3, 'When referring to the abstract quality of patience in general, no article is used.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c48', 'structure', NULL, 'structure_completion', '_____ Amazon River carries more water than any other river in the world.', '["A","An","The","(no article)"]', 2, 'Names of rivers require the definite article "the."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c49', 'structure', NULL, 'structure_completion', 'It is crucial that the medication _____ refrigerated at all times.', '["is","be","will be","being"]', 1, 'After "It is crucial that," the subjunctive base form "be" is required, regardless of tense.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c50', 'structure', NULL, 'structure_completion', 'Dr. Elena Cruz, _____ of the research team, presented the findings at the symposium.', '["the leader","leading","who leads","leads"]', 0, 'An appositive phrase renaming the subject should be a noun phrase, "the leader," set off by commas.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c51', 'structure', NULL, 'structure_completion', 'Although the results seemed inconclusive at first, the data _____ support the original hypothesis.', '["does","did","is","was"]', 1, 'The emphatic auxiliary "did" combines with the base verb "support" to stress a contrast with "seemed inconclusive" and matches the past-tense context; "does" is both present tense and singular, which does not fit.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c52', 'structure', NULL, 'structure_completion', '_____ was the unexpected drop in temperature that caused the pipes to freeze overnight.', '["It","There","This","That"]', 0, 'This is a cleft sentence ("It was X that...") used to emphasize "the unexpected drop in temperature"; "It" is the required subject for this structure.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c53', 'structure', NULL, 'structure_completion', '_____ the committee approved the budget came as a relief to the entire department.', '["What","That","Which","Because"]', 1, '"That" introduces a noun clause that can serve as the sentence''s subject; "What" would alter the meaning, "Which" needs an antecedent, and "Because" introduces an adverbial clause, which cannot function as a subject.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c54', 'structure', NULL, 'structure_completion', 'The workers arrived early _____ finish the project before the deadline.', '["so as","in order to","for to","so that"]', 1, '"In order to + base verb" expresses purpose; "so as" alone is incomplete, "for to" is not standard English, and "so that" requires a full clause, not an infinitive.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c55', 'structure', NULL, 'structure_completion', 'The teacher spoke slowly _____ all the students could understand the instructions.', '["so that","so as to","in order","for"]', 0, '"So that + clause" expresses purpose when followed by a full clause with a subject and verb; "so as to" and "in order" are followed by infinitives, not clauses.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c56', 'structure', NULL, 'structure_completion', '_____ the weather improves, the outdoor concert will likely be canceled due to the flood damage.', '["Even though","Even if","Because","Unless"]', 1, '"Even if" introduces a hypothetical or uncertain condition, which fits this speculative context; "Even though" is used for a known fact, not a hypothetical one.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c57', 'structure', NULL, 'structure_completion', '_____ the team had prepared thoroughly, the presentation did not go as planned.', '["Despite","Despite the fact that","Despite of","In spite"]', 1, '"Despite the fact that" is followed by a full clause; plain "Despite," "Despite of," and "In spite" (without "of") cannot be directly followed by a clause with a subject and verb.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c58', 'structure', NULL, 'structure_completion', 'The engineers reinforced the dam _____ it collapse during the flood season.', '["lest","unless","in case of","so"]', 0, '"Lest" is a formal conjunction meaning "for fear that," followed by the subjunctive base verb "collapse," and expresses a precaution against an undesired outcome.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c59', 'structure', NULL, 'structure_completion', 'The northern region relies heavily on manufacturing, _____ the southern region depends primarily on agriculture.', '["whereas","despite","unless","because"]', 0, '"Whereas" is used to contrast two facts, which fits the comparison between the two regions'' economies.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c60', 'structure', NULL, 'structure_completion', 'The old house looked as if it _____ abandoned for decades.', '["is","was","had been","has been"]', 2, '"As if/as though" describing a state resulting from an action that preceded the moment of looking takes the past perfect, "had been abandoned."', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c61', 'structure', NULL, 'structure_completion', 'I wish I _____ more time to prepare for the exam.', '["have","had","will have","has"]', 1, '"Wish" about a present unreal situation is followed by the past subjunctive ("had"), even though the meaning is present.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c62', 'structure', NULL, 'structure_completion', 'The manager would rather the report _____ submitted by Friday instead of Monday.', '["is","will be","were","be"]', 2, '"Would rather + subject + past subjunctive" is used when the subject differs from the speaker''s own action; here it should be "were submitted," not "is," "will be," or "be."', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c63', 'structure', NULL, 'structure_completion', 'It''s time the company _____ its outdated policies.', '["updates","update","updated","will update"]', 2, '"It''s time + subject + past tense" is an idiomatic subjunctive-like structure meaning it is now appropriate or overdue for something to happen, so the verb takes the simple past form, "updated."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-c64', 'structure', NULL, 'structure_completion', 'The organization has supported local schools _____ over two decades.', '["since","for","during","from"]', 1, '"For" is used with a duration of time ("for over two decades"), while "since" is used with a specific starting point.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e17', 'structure', NULL, 'structure_error_id', 'The new policy will effect how employees schedule their vacation time next year.', '["The new policy will effect","how employees schedule","their vacation time","next year"]', 0, '"Affect" (verb, meaning "to influence") is required here, not "effect," which is normally a noun; "effect" as a verb means "to bring about," which does not fit the intended meaning.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e18', 'structure', NULL, 'structure_error_id', 'The inheritance was divided between the four siblings according to their father''s will.', '["The inheritance was divided","between the four siblings","according to","their father''s will"]', 1, '"Between" is used for exactly two people or things; with more than two, as here with four siblings, "among" is required.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e19', 'structure', NULL, 'structure_error_id', 'After the long hike, she decided to lay down and rest for a while before continuing.', '["After the long hike,","she decided to lay down","and rest for a while","before continuing"]', 1, 'The intransitive verb "lie" (lie–lay–lain), meaning to recline, is needed here, not "lay," which is transitive and requires a direct object.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e20', 'structure', NULL, 'structure_error_id', 'Since the merger was completed, the two companies shared a single headquarters in the capital.', '["Since the merger was completed,","the two companies","shared a single headquarters","in the capital"]', 2, 'A clause introduced by "since" describing a state continuing up to the present requires the present perfect ("have shared"), not the simple past ("shared").', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e21', 'structure', NULL, 'structure_error_id', 'Arriving late to the meeting, the presentation had already begun without him.', '["Arriving late to the meeting,","the presentation had","already begun","without him"]', 1, 'The introductory participial phrase "Arriving late to the meeting" must logically modify a person, but the subject of the main clause is "the presentation," creating a dangling modifier; the subject should be a person, e.g., "he had already begun."', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e22', 'structure', NULL, 'structure_error_id', 'The committee are meeting tomorrow to discuss the new budget proposal.', '["The committee are meeting","tomorrow to discuss","the new budget","proposal"]', 0, 'In standard American English, collective nouns like "committee" take a singular verb when acting as a single unit, so it should be "The committee is meeting."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e23', 'structure', NULL, 'structure_error_id', 'Drivers should avoid to use their phones while operating a vehicle.', '["Drivers should avoid","to use their phones","while operating","a vehicle"]', 1, '"Avoid" is followed by a gerund, not an infinitive, so it should be "avoid using," not "avoid to use."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e24', 'structure', NULL, 'structure_error_id', 'Many students are interested on studying abroad during their junior year.', '["Many students are","interested on studying","abroad during","their junior year"]', 1, 'The correct preposition after "interested" is "in," not "on": "interested in studying."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e25', 'structure', NULL, 'structure_error_id', 'This year''s exam was more harder than last year''s, according to most students.', '["This year''s exam","was more harder than","last year''s,","according to most students"]', 1, '"Harder" already is the comparative form of "hard," so adding "more" creates a double comparative; it should simply be "harder than."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e26', 'structure', NULL, 'structure_error_id', 'She received an unique opportunity to study at the research institute.', '["She received","an unique opportunity","to study at","the research institute"]', 1, '"Unique" begins with a consonant sound ("yoo-neek"), so it should be preceded by "a," not "an": "a unique opportunity."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e27', 'structure', NULL, 'structure_error_id', 'The bridge was closed for repairs, however commuters found alternate routes without much difficulty.', '["The bridge was closed","for repairs, however","commuters found alternate routes","without much difficulty"]', 1, '"However" cannot join two independent clauses with only a comma; it should be preceded by a semicolon (or the clauses should be separated into two sentences): "for repairs; however,".', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e28', 'structure', NULL, 'structure_error_id', 'The new bridge is being build by a team of engineers from three different countries.', '["The new bridge","is being build by","a team of engineers","from three different countries"]', 1, 'The passive progressive requires the past participle "built," not the base form "build": "is being built."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e29', 'structure', NULL, 'structure_error_id', 'The laptop who crashed during the presentation had never malfunctioned before.', '["The laptop who crashed","during the presentation","had never","malfunctioned before"]', 0, '"Who" refers to people; since "laptop" is a thing, the relative pronoun should be "that" or "which": "The laptop that crashed."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e30', 'structure', NULL, 'structure_error_id', 'The witness couldn''t hardly remember any details about the incident that night.', '["The witness couldn''t hardly","remember any details","about the incident","that night"]', 0, '"Hardly" is already negative in meaning, so pairing it with "couldn''t" creates a double negative; it should be "could hardly remember."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e31', 'structure', NULL, 'structure_error_id', 'The manager and the supervisor is responsible for approving the new hires.', '["The manager and the supervisor","is responsible for","approving the new","hires"]', 1, 'A compound subject joined by "and" ("The manager and the supervisor") is treated as plural, so the verb should be "are responsible," not "is responsible."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e32', 'structure', NULL, 'structure_error_id', 'The coach made the players to run extra laps after they arrived late to practice.', '["The coach made","the players to run","extra laps after","they arrived late to practice"]', 1, 'The causative verb "make" is followed by the bare infinitive (base form) without "to": "made the players run," not "made the players to run."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e33', 'structure', NULL, 'structure_error_id', 'The organization revised it''s membership policy after receiving feedback from long-time members.', '["The organization revised","it''s membership policy","after receiving feedback","from long-time members"]', 1, 'The possessive form of "it" is "its" (no apostrophe); "it''s" is a contraction of "it is," which does not fit here.', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e34', 'structure', NULL, 'structure_error_id', 'Either the manager or the employees is responsible for submitting the report on time.', '["Either the manager","or the employees","is responsible for","submitting the report on time"]', 2, 'With "either...or," the verb agrees with the nearer subject, which here is the plural "employees," so it should be "are responsible."', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e35', 'structure', NULL, 'structure_error_id', 'I would rather to stay home tonight than go to the crowded concert.', '["I would rather to stay","home tonight","than go to","the crowded concert"]', 0, '"Would rather" is followed directly by the base form of the verb, without "to": "would rather stay," not "would rather to stay."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e36', 'structure', NULL, 'structure_error_id', 'Please let me know who you will invite to the ceremony next month.', '["Please let me know","who you will invite","to the ceremony","next month"]', 1, 'Since the pronoun functions as the object of "invite" (you will invite whom), the objective case "whom" is required in formal written English, not the subjective "who."', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e37', 'structure', NULL, 'structure_error_id', 'The reason the flight was delayed is because of a mechanical issue with the aircraft.', '["The reason the flight","was delayed is because of","a mechanical issue","with the aircraft"]', 1, '"The reason is because" is redundant since "reason" and "because" both indicate cause; it should be "the reason... is that" or simply "the flight was delayed because of."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e38', 'structure', NULL, 'structure_error_id', 'When I arrive at the airport yesterday, my flight had already been delayed by two hours.', '["When I arrive","at the airport yesterday,","my flight had already","been delayed by two hours"]', 0, 'The time clause refers to a completed past event ("yesterday"), so the verb should be in the simple past: "When I arrived."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e39', 'structure', NULL, 'structure_error_id', 'She is one of the few employees who consistently meets every deadline without exception.', '["She is one of","the few employees","who consistently meets","every deadline without exception"]', 2, 'The relative pronoun "who" refers to the plural noun "employees," so the verb should be plural: "who consistently meet," not "meets."', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e40', 'structure', NULL, 'structure_error_id', 'The new engine is not as efficient than the previous model in terms of fuel consumption.', '["The new engine","is not as efficient than","the previous model","in terms of fuel consumption"]', 1, 'The "as...as" construction requires "as" on both sides for an equal comparison, not "than": "not as efficient as the previous model."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e41', 'structure', NULL, 'structure_error_id', 'During the interview, the candidate acted very professional despite being nervous.', '["During the interview,","the candidate acted","very professional","despite being nervous"]', 2, 'The verb "acted" here describes manner and should be modified by the adverb "professionally," not the adjective "professional."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e42', 'structure', NULL, 'structure_error_id', 'Collecting rare stamps have been her hobby since she was a child.', '["Collecting rare stamps","have been her hobby","since she was","a child"]', 1, 'A gerund phrase functioning as the subject ("Collecting rare stamps") is treated as singular, so the verb should be "has been," not "have been."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e43', 'structure', NULL, 'structure_error_id', 'She use to walk to school every morning before her family bought a car.', '["She use to walk","to school every morning","before her family","bought a car"]', 0, 'The past habitual expression requires "used to," not "use to": "She used to walk."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e44', 'structure', NULL, 'structure_error_id', 'There is a wallet and several keys underneath the front seat of the car.', '["There is a wallet","and several keys","underneath the front seat","of the car"]', 0, 'The subject following "there" is the compound "a wallet and several keys," which is plural, so the verb should be "There are," not "There is."', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e45', 'structure', NULL, 'structure_error_id', 'The results of this experiment are similar with those reported in earlier studies.', '["The results of","this experiment are","similar with those reported","in earlier studies"]', 2, 'The correct idiom is "similar to," not "similar with": "similar to those reported."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e46', 'structure', NULL, 'structure_error_id', 'Each and every one of the applicants were interviewed twice before a decision was made.', '["Each and every one","of the applicants were interviewed","twice before","a decision was made"]', 1, '"Each and every one" is grammatically singular, so the verb should be "was interviewed," not "were interviewed."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e47', 'structure', NULL, 'structure_error_id', 'If the government increases funding for public transit, more people would use the buses instead of driving.', '["If the government increases","funding for public transit,","more people would use","the buses instead of driving"]', 0, 'The main clause uses the hypothetical "would use," which pairs with a past-tense if-clause in the second conditional; it should be "If the government increased," not "increases," to match.', 'hard', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e48', 'structure', NULL, 'structure_error_id', 'Beside working as a nurse, she volunteers at an animal shelter every weekend.', '["Beside working as a nurse,","she volunteers at","an animal shelter","every weekend"]', 0, '"Besides" (meaning "in addition to") is needed here, not "beside" (meaning "next to"): "Besides working as a nurse."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e49', 'structure', NULL, 'structure_error_id', 'Prices have raised steadily over the past decade due to inflation.', '["Prices have raised","steadily over","the past decade","due to inflation"]', 0, '"Rise" is the intransitive verb used for something increasing on its own (rise–rose–risen); "raise" is transitive and requires a direct object, so it should be "Prices have risen."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e50', 'structure', NULL, 'structure_error_id', 'Could you borrow me your calculator for the duration of the exam?', '["Could you borrow me","your calculator","for the duration","of the exam"]', 0, '"Lend" means to give something temporarily, while "borrow" means to receive something temporarily; since the speaker wants to receive the calculator, it should be "Could you lend me."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e51', 'structure', NULL, 'structure_error_id', 'The news about the merger were leaked to journalists before the official announcement.', '["The news about","the merger were leaked","to journalists before","the official announcement"]', 1, '"News" is an uncountable noun that always takes a singular verb in English, so it should be "the news... was leaked," not "were leaked."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e52', 'structure', NULL, 'structure_error_id', 'It was so complicated problem that even the professor took an hour to solve it.', '["It was so complicated problem","that even the professor","took an hour","to solve it"]', 0, 'Before a noun, "such a/an + adjective + noun" is used, not "so"; it should be "It was such a complicated problem."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e53', 'structure', NULL, 'structure_error_id', 'Despite that the weather was poor, the outdoor concert continued as scheduled.', '["Despite that the weather","was poor,","the outdoor concert continued","as scheduled"]', 0, '"Despite" is a preposition and cannot be directly followed by a "that" clause; it should be "Despite the fact that" or simply "Although the weather was poor."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e54', 'structure', NULL, 'structure_error_id', 'She is best qualified candidate for the position, based on her extensive experience.', '["She is best qualified","candidate for the position,","based on her","extensive experience"]', 0, 'Superlative adjectives require the definite article "the": it should be "the best qualified candidate."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e55', 'structure', NULL, 'structure_error_id', 'She had her car repair by a mechanic the day before the road trip.', '["She had her car repair","by a mechanic","the day before","the road trip"]', 0, 'The causative structure "have something done" requires the past participle, not the base form: "had her car repaired," not "repair."', 'easy', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-struct-e56', 'structure', NULL, 'structure_error_id', 'The majority of the students has completed the assignment ahead of the deadline.', '["The majority of","the students has completed","the assignment","ahead of the deadline"]', 1, '"The majority of" followed by a plural noun ("students") takes a plural verb: "the students have completed," not "has completed."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-1', 'reading', 'p-horse', 'reading_comprehension', 'What is the main purpose of the passage?', '["To argue that horses were never domesticated on the Eurasian steppe","To describe how genetic research has revised earlier ideas about where and when horses were domesticated","To explain the biological differences between wild and domestic horses","To criticize archaeologists for relying on indirect evidence"]', 1, 'The passage traces how genetic studies shifted the accepted account of horse domestication away from the earlier Kazakhstan-steppe theory toward the Volga-Don region.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-2', 'reading', 'p-horse', 'reading_comprehension', 'According to the passage, what evidence originally supported the theory that horses were domesticated in Kazakhstan?', '["Genetic comparisons of ancient horse DNA","Cave paintings depicting horseback riding","Wear patterns on horse teeth and large deposits of horse bones","Written records from early steppe civilizations"]', 2, 'The passage states the earlier theory "rested largely on indirect evidence: wear patterns on horse teeth... and unusually large deposits of horse bones."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-3', 'reading', 'p-horse', 'reading_comprehension', 'The word "prevailing" in the passage is closest in meaning to', '["outdated","dominant","controversial","incorrect"]', 1, '"Prevailing" describes the view that was most widely accepted at the time, i.e., the dominant view.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-4', 'reading', 'p-horse', 'reading_comprehension', 'It can be inferred from the passage that the horses from the lower Volga-Don region spread quickly because', '["they were transported by boat across major rivers","they had traits that made them easier to control and ride","local horse populations had already died out","they were traded exclusively among steppe nomads"]', 1, 'The passage links the rapid spread to "a calmer temperament and a stronger backbone," traits that made the horses easier to control and better suited to riding.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-5', 'reading', 'p-horse', 'reading_comprehension', 'The word "This population" in paragraph 2 refers to', '["modern domestic horses","researchers studying ancient DNA","the horses from the lower Volga-Don region","horses on the Kazakhstan steppe"]', 2, 'The phrase immediately follows the description of "a single population that lived in the lower Volga-Don region."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-horse-6', 'reading', 'p-horse', 'reading_comprehension', 'According to the passage, all of the following are mentioned as being affected by horse domestication EXCEPT', '["transportation","warfare","trade","agriculture"]', 3, 'The final paragraph mentions transportation, warfare, and trade; agriculture is not mentioned in the passage.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-1', 'reading', 'p-coral', 'reading_comprehension', 'What is the passage mainly about?', '["The variety of species that live in coral reefs","How rising water temperatures disrupt the relationship between coral and algae","Methods scientists use to measure ocean temperature","The life cycle of zooxanthellae algae"]', 1, 'The passage centers on how heat stress breaks down the coral-algae partnership, causing bleaching.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-2', 'reading', 'p-coral', 'reading_comprehension', 'According to the passage, what do zooxanthellae algae provide to coral polyps?', '["Protection from predators","A hard calcium carbonate skeleton","Nutrients through photosynthesis","Compounds needed for reproduction"]', 2, 'The passage states the algae "photosynthesize and supply the coral with nutrients."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-3', 'reading', 'p-coral', 'reading_comprehension', 'The word "translucent" in the passage is closest in meaning to', '["brightly colored","partly transparent","extremely fragile","thickly layered"]', 1, '"Translucent" describes tissue through which the white skeleton becomes visible, i.e., partly see-through.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-4', 'reading', 'p-coral', 'reading_comprehension', 'It can be inferred from the passage that a bleached coral reef would appear', '["darker than a healthy reef","the same color as a healthy reef","paler or whiter than a healthy reef","covered in algae"]', 2, 'Since bleaching exposes the white skeleton after algae (which provide color) are expelled, a bleached reef would look paler or white.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-5', 'reading', 'p-coral', 'reading_comprehension', 'The word "this partnership" in paragraph 2 refers to', '["the relationship between coral polyps and zooxanthellae algae","the relationship between scientists and reef ecosystems","the connection between ocean currents and temperature","the balance between predators and prey on the reef"]', 0, 'Paragraph 1 establishes the coral-algae partnership, which paragraph 2 refers back to as "this partnership."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-coral-6', 'reading', 'p-coral', 'reading_comprehension', 'According to the passage, all of the following are true about coral recovery EXCEPT', '["bleached coral can sometimes recover if temperatures return to normal quickly","coral grows only a few centimeters per year","recovery from severe bleaching can take decades","coral recovers fully within a single year regardless of damage"]', 3, 'The passage states recovery from severe bleaching "can take decades," directly contradicting full recovery within a single year.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-1', 'reading', 'p-impressionism', 'reading_comprehension', 'What is the main topic of the passage?', '["The biography of Claude Monet","The origin and development of Impressionist painting","The rules of the official Salon exhibition","A comparison between Impressionism and modern art"]', 1, 'The passage traces how Impressionism began as an insult and developed into a recognized artistic movement.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-2', 'reading', 'p-impressionism', 'reading_comprehension', 'According to the passage, how did the term "Impressionist" originate?', '["The artists chose it themselves before their first exhibition","A critic used it to mock a painting by Claude Monet","It was the name of the gallery where the artists exhibited","It referred to a technique taught at the official Salon"]', 1, 'The passage states a critic, "mocking a Claude Monet painting... coined the term ''Impressionist'' as an insult."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-3', 'reading', 'p-impressionism', 'reading_comprehension', 'The word "transient" in the passage is closest in meaning to', '["permanent","brief","colorful","natural"]', 1, '"Transient effects of natural light" refers to light effects that change quickly, i.e., brief ones.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-4', 'reading', 'p-impressionism', 'reading_comprehension', 'It can be inferred from the passage that the official Salon exhibition preferred paintings that were', '["painted quickly outdoors","based on everyday, modern subjects","carefully composed with smooth, blended surfaces","rejected by professional art dealers"]', 2, 'The passage contrasts the Impressionists'' visible brushstrokes with "the smooth, blended surfaces the Salon prized."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-5', 'reading', 'p-impressionism', 'reading_comprehension', 'The word "their" in paragraph 3 refers to', '["the critics''","the dealers''","the artists''","the Salon''s"]', 2, 'The sentence describes dealers promoting "the artists'' work," so "their" refers to the artists.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-imp-6', 'reading', 'p-impressionism', 'reading_comprehension', 'According to the passage, all of the following are mentioned as subjects favored by Impressionist painters EXCEPT', '["train stations","cafes","riverside gatherings","mythological scenes"]', 3, 'The passage lists train stations, cafes, and riverside gatherings as favored subjects, while mythological scenes are described as subjects the Impressionists moved away from.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-1', 'reading', 'p-insulin', 'reading_comprehension', 'What is the passage mainly about?', '["The symptoms of type 1 diabetes in children","How insulin was discovered and rapidly developed into a treatment","The history of the Nobel Prize in Physiology or Medicine","Surgical techniques used on laboratory animals in the 1920s"]', 1, 'The passage traces the discovery of insulin from early research on the pancreas to its rapid development into a lifesaving treatment.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-2', 'reading', 'p-insulin', 'reading_comprehension', 'According to the passage, why had earlier attempts to isolate the pancreatic substance failed?', '["Researchers could not identify which organ was involved","Digestive enzymes in the pancreas broke down the substance before it could be extracted","No diabetic patients were willing to participate in trials","The equipment needed for extraction had not yet been invented"]', 1, 'The passage states earlier attempts failed "largely because digestive enzymes in the pancreas broke down the substance before it could be extracted in usable form."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-3', 'reading', 'p-insulin', 'reading_comprehension', 'The word "degenerate" in the passage is closest in meaning to', '["multiply","break down","become active","relocate"]', 1, '"Degenerate" describes tissue deteriorating after the pancreatic duct was tied off, i.e., breaking down.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-4', 'reading', 'p-insulin', 'reading_comprehension', 'It can be inferred from the passage that tying off the pancreatic duct was significant because it', '["increased the number of insulin-producing cells","allowed the enzyme-producing tissue to be destroyed while preserving insulin-producing cells","eliminated the need for laboratory animals","cured the dogs'' diabetes permanently"]', 1, 'The passage explains this technique caused enzyme-producing tissue to degenerate "while preserving the cells now known to produce insulin."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-5', 'reading', 'p-insulin', 'reading_comprehension', 'The word "it" in paragraph 2, in the phrase "to make it safe for humans," refers to', '["the pancreatic duct","the extraction process","the substance/extract","the laboratory"]', 2, 'Collip refined the extraction process to make the extracted substance safe for human use.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-insulin-6', 'reading', 'p-insulin', 'reading_comprehension', 'According to the passage, all of the following people are mentioned as contributing to the discovery of insulin EXCEPT', '["Frederick Banting","Charles Best","James Collip","Alexander Fleming"]', 3, 'Banting, Best, and Collip (along with Macleod) are named in the passage; Alexander Fleming is not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-1', 'reading', 'p-urban-heat', 'reading_comprehension', 'What is the main purpose of the passage?', '["To explain the causes and effects of the urban heat island effect and how cities are addressing it","To compare temperatures in different cities around the world","To argue that urban development should be halted","To describe how air conditioning units work"]', 0, 'The passage explains what causes urban heat islands, their consequences, and mitigation strategies cities are trying.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-2', 'reading', 'p-urban-heat', 'reading_comprehension', 'According to the passage, what is the primary cause of the urban heat island effect?', '["Waste heat from vehicles alone","Materials like asphalt and dark rooftops absorbing and releasing solar radiation","The height of buildings blocking sunlight","A lack of rainfall in cities"]', 1, 'The passage states the primary cause is that materials like asphalt and dark rooftops "absorb far more solar radiation... then slowly release that stored heat after sunset."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-3', 'reading', 'p-urban-heat', 'reading_comprehension', 'The word "compound" in the passage is closest in meaning to', '["reduce","explain","intensify","measure"]', 2, '"Compound the effect" means other factors make the effect stronger, i.e., intensify it.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-4', 'reading', 'p-urban-heat', 'reading_comprehension', 'It can be inferred from the passage that green roofs help mitigate the urban heat island effect because they', '["generate electricity for the building","reduce the amount of solar energy absorbed by rooftop surfaces","eliminate the need for tall buildings","increase waste heat from air conditioning"]', 1, 'Green roofs are listed among strategies intended to "reduce how much solar energy urban surfaces absorb and retain."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-5', 'reading', 'p-urban-heat', 'reading_comprehension', 'The word "it" in paragraph 1, in the phrase "release that stored heat," refers to heat stored in', '["rural vegetation","the atmosphere generally","urban construction materials such as asphalt and rooftops","air conditioning units"]', 2, 'The heat referred to is the solar radiation absorbed by urban construction materials during the day.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-heat-6', 'reading', 'p-urban-heat', 'reading_comprehension', 'According to the passage, all of the following are mentioned as mitigation strategies EXCEPT', '["reflective roofing materials","expanded tree canopy coverage","green roofs","banning private vehicles"]', 3, 'The passage names reflective roofing, tree canopy expansion, and green roofs as mitigation strategies; banning vehicles is not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-1', 'reading', 'p-silk-road', 'reading_comprehension', 'What is the main idea of the passage?', '["The Silk Road was primarily a route for trading silk between China and Europe","The Silk Road facilitated a broad exchange of goods, ideas, and technologies with lasting economic significance","The Silk Road declined because of religious conflict","Papermaking technology was invented along the Silk Road"]', 1, 'The passage emphasizes that the Silk Road carried far more than silk and had a lasting economic and cultural legacy.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-2', 'reading', 'p-silk-road', 'reading_comprehension', 'According to the passage, what caused the decline of the Silk Road network?', '["The invention of paper","The rise of direct sea trade between Europe and Asia","A decline in demand for silk","The spread of Buddhism"]', 1, 'The passage states the network declined "following the rise of direct sea trade between Europe and Asia."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-3', 'reading', 'p-silk-road', 'reading_comprehension', 'The word "disseminated" in the passage is closest in meaning to', '["destroyed","spread","translated","hidden"]', 1, '"Disseminated" describes how information was recorded and spread after papermaking reached new regions.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-4', 'reading', 'p-silk-road', 'reading_comprehension', 'It can be inferred from the passage that cities like Samarkand and Kashgar prospered mainly because they', '["produced large quantities of silk","were located strategically along trade routes","had large populations of merchants who manufactured goods","banned foreign traders from entering"]', 1, 'The passage states these cities prospered "largely because of their strategic locations rather than their own manufacturing output."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-5', 'reading', 'p-silk-road', 'reading_comprehension', 'The word "its" in paragraph 1, in the phrase "the network''s decline," refers to', '["China''s","the Mediterranean''s","the Silk Road''s","Europe''s"]', 2, 'The phrase describes the decline of the Silk Road network described earlier in the sentence.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-silkroad-6', 'reading', 'p-silk-road', 'reading_comprehension', 'According to the passage, all of the following are mentioned as having traveled along the Silk Road EXCEPT', '["spices","papermaking technology","Buddhism","firearms"]', 3, 'The passage mentions spices, papermaking technology, and the spread of Buddhism; firearms are not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-1', 'reading', 'p-photosynthesis', 'reading_comprehension', 'What is the passage mainly about?', '["The chemical structure of RuBisCO","How C4 photosynthesis helps certain plants cope with hot, dry conditions more efficiently than C3 photosynthesis","The history of maize cultivation","Methods for irrigating crops in arid regions"]', 1, 'The passage explains the mechanism of C4 photosynthesis and why it gives certain plants an advantage in hot, dry climates over standard C3 photosynthesis.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-2', 'reading', 'p-photosynthesis', 'reading_comprehension', 'According to the passage, what problem does photorespiration cause in C3 plants?', '["It prevents leaf pores from closing","It reduces the energy available for growth because RuBisCO binds oxygen instead of carbon dioxide","It causes plants to lose their leaves","It increases the rate of water loss through roots"]', 1, 'The passage states photorespiration is "a wasteful side reaction... that reduces the energy available for growth" when RuBisCO binds oxygen instead of carbon dioxide.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-3', 'reading', 'p-photosynthesis', 'reading_comprehension', 'The word "suppressing" in the passage is closest in meaning to', '["causing","measuring","preventing","accelerating"]', 2, '"Suppressing the conditions that lead to photorespiration" means preventing those conditions from occurring.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-4', 'reading', 'p-photosynthesis', 'reading_comprehension', 'It can be inferred from the passage that C4 plants have an advantage over C3 plants primarily in', '["cold, cloudy climates","hot, sunny, and relatively dry climates","climates with very high rainfall only","environments with no sunlight"]', 1, 'The passage explains C4 plants can conserve water while maintaining photosynthesis in "hot, sunny climates," giving them an advantage there.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-5', 'reading', 'p-photosynthesis', 'reading_comprehension', 'The word "these plants" in paragraph 2 refers to', '["all plants that use C3 photosynthesis","maize, sugarcane, and sorghum","researchers studying photosynthesis","plants found only in tropical rainforests"]', 1, 'Paragraph 2 opens by naming maize, sugarcane, and sorghum as the C4 plants being described.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-photosynthesis-6', 'reading', 'p-photosynthesis', 'reading_comprehension', 'According to the passage, all of the following are mentioned as examples of C4 plants EXCEPT', '["maize","sugarcane","sorghum","wheat"]', 3, 'The passage names maize, sugarcane, and sorghum as C4 plants; wheat is not mentioned as one.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-1', 'reading', 'p-bronze-age', 'reading_comprehension', 'What is the passage mainly about?', '["The daily life of Mycenaean Greek citizens","The likely causes and regional consequences of the Bronze Age Collapse","The invention of bronze metallurgy","A comparison between Egyptian and Hittite writing systems"]', 1, 'The passage discusses the possible causes of the Bronze Age Collapse and how its consequences varied by region.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-2', 'reading', 'p-bronze-age', 'reading_comprehension', 'According to the passage, what happened to writing systems in several regions after the collapse?', '["They were simplified but continued in use","They disappeared for centuries","They were replaced by a single universal script","They were used only by the Sea Peoples"]', 1, 'The passage states writing systems "disappeared in several regions for centuries afterward."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-3', 'reading', 'p-bronze-age', 'reading_comprehension', 'The word "overwhelm" in the passage is closest in meaning to', '["support","explain","exceed the capacity of","postpone"]', 2, '"Overwhelm these interconnected societies" means the combined stresses exceeded what the societies could withstand.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-4', 'reading', 'p-bronze-age', 'reading_comprehension', 'It can be inferred from the passage that trade in tin was significant because', '["tin was used as currency across the region","tin was needed to produce bronze, linking these societies economically","tin was the primary food source for coastal populations","tin mining caused the initial drought"]', 1, 'The passage explains societies had "grown economically interdependent through trade in tin and other resources needed to produce bronze."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-5', 'reading', 'p-bronze-age', 'reading_comprehension', 'The word "these societies" in paragraph 2 refers to', '["modern historians","the civilizations affected by the Bronze Age Collapse","the Sea Peoples specifically","only the Egyptian civilization"]', 1, 'The phrase refers back to the civilizations described in paragraph 1 as experiencing the collapse.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bronze-age-6', 'reading', 'p-bronze-age', 'reading_comprehension', 'According to the passage, all of the following are mentioned as factors or evidence related to the collapse EXCEPT', '["raids by the Sea Peoples","a period of prolonged drought","the disruption of trade networks","a major volcanic eruption"]', 3, 'The passage mentions Sea Peoples raids, drought, and trade disruption; a volcanic eruption is not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-1', 'reading', 'p-loss-aversion', 'reading_comprehension', 'What is the passage mainly about?', '["The mathematical formula behind expected value","How loss aversion causes people to deviate from purely rational economic behavior","The biography of Daniel Kahneman","Why retailers offer limited-time discounts"]', 1, 'The passage explains loss aversion and gives several examples of how it causes behavior that departs from rational economic models.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-2', 'reading', 'p-loss-aversion', 'reading_comprehension', 'According to the passage, what did Kahneman and Tversky find about how people experience losses and gains?', '["People feel gains and losses with equal intensity","People feel the pain of a loss about twice as intensely as an equivalent gain","People barely notice small financial losses","People prefer losses to gains in most situations"]', 1, 'The passage states people "feel the pain of a loss roughly twice as intensely as the pleasure of an equivalent gain."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-3', 'reading', 'p-loss-aversion', 'reading_comprehension', 'The word "asymmetry" in the passage is closest in meaning to', '["balance","imbalance","similarity","calculation"]', 1, 'The unequal intensity of feeling losses versus gains is described as an asymmetry, i.e., an imbalance.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-4', 'reading', 'p-loss-aversion', 'reading_comprehension', 'It can be inferred from the passage that an investor influenced by loss aversion would most likely', '["sell a losing stock immediately to avoid further risk","hold onto a declining stock longer than a rational strategy would suggest","refuse to invest in the stock market at all","treat gains and losses exactly the same way"]', 1, 'The passage states investors "often hold onto declining stocks far longer than a purely rational strategy would recommend."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-5', 'reading', 'p-loss-aversion', 'reading_comprehension', 'The word "which" in paragraph 3, in the phrase "which tends to be more motivating," refers to', '["offering a limited-time discount framed as a potential gain","framing a limited-time discount as an opportunity to avoid losing out","the retirement savings program","the coin-flip bet described in paragraph 2"]', 1, 'The sentence contrasts framing a discount as avoiding a loss (more motivating) with framing it as a potential gain.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-loss-aversion-6', 'reading', 'p-loss-aversion', 'reading_comprehension', 'According to the passage, all of the following are mentioned as examples influenced by loss aversion EXCEPT', '["investors holding onto declining stocks","people rejecting a fair coin-flip bet","retailers framing discounts around avoiding loss","consumers preferring generic brands over name brands"]', 3, 'The passage mentions investors, the coin-flip bet, and retail framing as examples; brand preference is not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-1', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'What is the passage mainly about?', '["Alfred Wegener''s personal life","How the theory of continental drift evolved into the modern theory of plate tectonics","The formation of mountain ranges specifically","Methods used to predict earthquakes"]', 1, 'The passage traces Wegener''s original theory through the discovery of seafloor spreading to the modern theory of plate tectonics.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-2', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'According to the passage, why did most geologists initially reject Wegener''s theory?', '["His evidence about coastlines was considered fabricated","He could not identify a plausible mechanism for continents moving through solid ocean floor","He refused to publish his findings","Fossil evidence contradicted his theory"]', 1, 'The passage states geologists rejected the theory "largely because he could not identify a plausible mechanism."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-3', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'The word "plausible" in the passage is closest in meaning to', '["impossible","believable","famous","ancient"]', 1, 'A "plausible mechanism" is one that is believable or credible.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-4', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'It can be inferred from the passage that the discovery of seafloor spreading was important because it', '["proved that continents do not move at all","provided a mechanism that made continental drift scientifically credible","disproved the existence of mid-ocean ridges","showed that Pangaea never existed"]', 1, 'The passage states seafloor spreading "provided the missing mechanism" that Wegener''s theory had lacked.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-5', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'The word "This framework" in paragraph 3 refers to', '["Wegener''s original 1912 theory","the technology used to map the ocean floor","the modern theory of plate tectonics","the distribution of fossils across continents"]', 2, '"This framework" refers to the modern theory of plate tectonics described earlier in the same paragraph.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-plate-tectonics-6', 'reading', 'p-plate-tectonics', 'reading_comprehension', 'According to the passage, all of the following are mentioned as evidence or phenomena related to plate tectonics EXCEPT', '["matching coastlines of South America and Africa","mid-ocean ridges","the distribution of earthquakes and volcanoes","the discovery of a ninth continent"]', 3, 'The passage mentions matching coastlines, mid-ocean ridges, and earthquake/volcano distribution; a ninth continent is not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-1', 'reading', 'p-printing-press', 'reading_comprehension', 'What is the passage mainly about?', '["The biography of Johannes Gutenberg","How the printing press transformed the production and spread of written knowledge in Europe","The history of papermaking in East Asia","The religious teachings of Martin Luther"]', 1, 'The passage explains Gutenberg''s printing system and its wide-ranging effects on the spread of knowledge in Europe.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-2', 'reading', 'p-printing-press', 'reading_comprehension', 'According to the passage, what technologies did Gutenberg combine in his printing system?', '["Woodblock carving and handwritten calligraphy","Movable metal type, oil-based ink, and a modified wine press","Paper made from wood pulp and a steam-powered press","Movable type invented by Martin Luther"]', 1, 'The passage states Gutenberg "combined movable metal type, an oil-based ink suited to metal surfaces, and a modified wine press."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-3', 'reading', 'p-printing-press', 'reading_comprehension', 'The word "accelerate" in the passage is closest in meaning to', '["slow down","speed up","prevent","record"]', 1, '"Accelerate the spread of new scientific ideas" means to speed up that spread.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-4', 'reading', 'p-printing-press', 'reading_comprehension', 'It can be inferred from the passage that before the printing press, access to books was', '["available equally to all social classes","limited mainly to monasteries, universities, and wealthy patrons","restricted entirely to religious texts","more widespread than after the printing press"]', 1, 'The passage states hand-copied books were "limited to a small number of copies held by monasteries, universities, and wealthy patrons."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-5', 'reading', 'p-printing-press', 'reading_comprehension', 'The word "earlier reform movements" in paragraph 3 is used to contrast with', '["the speed at which Martin Luther could distribute his writings using the printing press","the invention of movable type in East Asia","the wine press used by Gutenberg","the rise in literacy rates"]', 0, 'The passage contrasts how quickly Luther could spread his writings with the printing press against reformers who lacked it earlier.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-printing-press-6', 'reading', 'p-printing-press', 'reading_comprehension', 'According to the passage, all of the following are mentioned as effects of the printing press EXCEPT', '["a drop in the cost of producing books","faster spread of scientific ideas","rising literacy rates","the abolition of monasteries"]', 3, 'The passage mentions lower book costs, faster idea spread, and rising literacy; the abolition of monasteries is not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-1', 'reading', 'p-octopus', 'reading_comprehension', 'What is the passage mainly about?', '["The diet of wild octopuses","The octopus''s unusual nervous system and its role in rapid camouflage","A comparison between octopuses and squid","How chromatophores are used in human medical research"]', 1, 'The passage explains the octopus''s distributed nervous system and how it supports rapid camouflage.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-2', 'reading', 'p-octopus', 'reading_comprehension', 'According to the passage, where are roughly two-thirds of an octopus''s neurons located?', '["In the central brain","In the eyes","Distributed throughout its eight arms","In the skin''s chromatophores"]', 2, 'The passage states "roughly two-thirds of an octopus''s several hundred million neurons are distributed throughout its eight arms."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-3', 'reading', 'p-octopus', 'reading_comprehension', 'The word "distributed" in the passage is closest in meaning to', '["concentrated","spread out","removed","duplicated"]', 1, '"Distributed throughout its eight arms" means spread out across the arms rather than concentrated in one place.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-4', 'reading', 'p-octopus', 'reading_comprehension', 'It can be inferred from the passage that octopus camouflage is puzzling to researchers mainly because', '["octopuses cannot move their arms independently","octopuses appear to be colorblind yet can match colors in their environment","chromatophores are found only in a few octopus species","octopuses never change their skin texture"]', 1, 'The passage notes this ability is puzzling because octopuses "are believed to be colorblind" yet can still match surrounding colors.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-5', 'reading', 'p-octopus', 'reading_comprehension', 'The word "this ability" in paragraph 2 refers to', '["the octopus''s distributed nervous system","the octopus''s near-instantaneous camouflage","the octopus''s sense of touch","the octopus''s diet"]', 1, '"This ability" refers back to the near-instantaneous camouflage introduced at the start of paragraph 2.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-octopus-6', 'reading', 'p-octopus', 'reading_comprehension', 'According to the passage, all of the following are mentioned as being involved in octopus camouflage EXCEPT', '["chromatophores","papillae that reshape skin texture","light-sensitive proteins in the skin","color-sensitive cone cells in the eyes"]', 3, 'The passage states octopuses lack color-sensitive cone cells; chromatophores, papillae, and skin proteins are all mentioned as involved.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-1', 'reading', 'p-dust-bowl', 'reading_comprehension', 'What is the passage mainly about?', '["The geography of the Great Plains","The causes and consequences of the Dust Bowl","The history of wheat prices in the United States","Federal tax policy during the 1930s"]', 1, 'The passage explains the natural and human causes of the Dust Bowl and its effects on farming families and policy.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-2', 'reading', 'p-dust-bowl', 'reading_comprehension', 'According to the passage, what practice contributed to the exposure of topsoil before the Dust Bowl?', '["Farmers planting deep-rooted prairie grasses","Farmers plowing under native prairie grasses to plant wheat","Farmers irrigating their fields excessively","Farmers abandoning their land entirely"]', 1, 'The passage states farmers "had plowed under vast areas of native prairie grasses to plant wheat."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-3', 'reading', 'p-dust-bowl', 'reading_comprehension', 'The word "anchored" in the passage is closest in meaning to', '["loosened","secured","fertilized","flooded"]', 1, 'Prairie grasses "anchored the soil" means they held it securely in place.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-4', 'reading', 'p-dust-bowl', 'reading_comprehension', 'It can be inferred from the passage that the Dust Bowl would have been less severe if', '["wheat prices had risen even further","native prairie grasses had not been plowed under","the drought had lasted only a single year","more families had migrated to California"]', 1, 'Since the grasses had anchored the soil and prevented erosion, leaving them intact would likely have reduced the severity of the storms.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-5', 'reading', 'p-dust-bowl', 'reading_comprehension', 'The word "them" in paragraph 2, in the phrase "without them," refers to', '["wheat farmers","deep-rooted prairie grasses","dust storms","federal conservation programs"]', 1, 'The sentence describes topsoil losing its anchor "without" the deep-rooted prairie grasses mentioned just before.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dust-bowl-6', 'reading', 'p-dust-bowl', 'reading_comprehension', 'According to the passage, all of the following are mentioned as responses to or causes of the Dust Bowl EXCEPT', '["a multi-year drought beginning in 1931","plowing under native prairie grasses","contour plowing and windbreak trees promoted by the government","the construction of large-scale irrigation canals"]', 3, 'The passage mentions the drought, plowing practices, and government conservation programs; irrigation canals are not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-1', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'What is the passage mainly about?', '["The biography of the Medici family","How the patronage system shaped the production and direction of Renaissance art","The techniques used to create the pigment ultramarine","A comparison between Renaissance and modern art markets"]', 1, 'The passage explains how the patronage system influenced what Renaissance artists produced and how they competed for commissions.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-2', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'According to the passage, what might a patron''s commission specify?', '["Only the general subject matter, with no other requirements","The artist''s political opinions","Exact dimensions, materials, and the number of figures to be included","The exact selling price of the finished work"]', 2, 'The passage states commissions could specify "exact dimensions, materials such as expensive pigments... and even the number of figures to be included."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-3', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'The word "constrained" in the passage is closest in meaning to', '["expanded","limited","ignored","rewarded"]', 1, 'Patron preferences that "constrained" creative choices means they limited those choices.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-4', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'It can be inferred from the passage that Renaissance artists'' creative choices were often influenced by', '["government censorship laws","the specific preferences and demands of their patrons","the absence of any competition among artists","a complete lack of financial concerns"]', 1, 'The passage explains artists "had strong incentives to satisfy a patron''s specific tastes and demands."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-5', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'The word "This arrangement" in paragraph 2 refers to', '["the competition among artists for commissions","the patronage system described in paragraph 1","the technique of linear perspective","the political structure of Florence"]', 1, '"This arrangement" refers back to the patronage system introduced in paragraph 1.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-renaissance-patronage-6', 'reading', 'p-renaissance-patronage', 'reading_comprehension', 'According to the passage, all of the following are mentioned as motivations or effects related to patronage EXCEPT', '["displaying wealth and political influence","driving technical innovation through competition","satisfying a patron''s specific tastes","eliminating the need for skilled artists"]', 3, 'The passage mentions wealth display, competitive innovation, and satisfying patrons; eliminating skilled artists is not mentioned and contradicts the passage.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-1', 'reading', 'p-bird-navigation', 'reading_comprehension', 'What is the passage mainly about?', '["The reasons birds migrate in the first place","The multiple navigational systems migratory birds use to travel long distances","The specific migration routes of one bird species","How researchers tag birds for tracking studies"]', 1, 'The passage describes several overlapping navigational systems, including magnetoreception, celestial cues, and mental maps.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-2', 'reading', 'p-bird-navigation', 'reading_comprehension', 'According to the passage, what is magnetoreception?', '["The ability to see ultraviolet light","The ability to detect Earth''s magnetic field","The ability to smell familiar landscapes","The ability to remember visual landmarks"]', 1, 'The passage defines magnetoreception as "the ability to detect Earth''s magnetic field."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-3', 'reading', 'p-bird-navigation', 'reading_comprehension', 'The word "innate" in the passage is closest in meaning to', '["learned through practice","present from birth","extremely rare","impossible to study"]', 1, 'Abilities that are "innate rather than learned" are present from birth.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-4', 'reading', 'p-bird-navigation', 'reading_comprehension', 'It can be inferred from the passage that young birds completing their first migration successfully suggests that', '["all navigational ability is learned from adult birds","at least some navigational ability is present without prior experience","young birds cannot navigate using magnetic fields","migration routes never change between generations"]', 1, 'The passage states young birds "often complete the journey successfully even without prior experience or adult guidance," suggesting innate ability.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-5', 'reading', 'p-bird-navigation', 'reading_comprehension', 'The word "this sense" in paragraph 2 refers to', '["the ability to see stars","the ability to detect Earth''s magnetic field","the ability to smell nesting sites","the ability to build mental maps"]', 1, '"This sense" refers to magnetoreception, the magnetic-field-detecting sense described earlier in the paragraph.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-bird-navigation-6', 'reading', 'p-bird-navigation', 'reading_comprehension', 'According to the passage, all of the following are mentioned as tools migratory birds may use to navigate EXCEPT', '["Earth''s magnetic field","the position of the sun and stars","visual landmarks and smell","radio signals from other birds"]', 3, 'The passage mentions magnetic fields, celestial cues, and landmarks/smell; radio signals are not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-1', 'reading', 'p-assembly-line', 'reading_comprehension', 'What is the passage mainly about?', '["The biography of Henry Ford","How the moving assembly line transformed manufacturing efficiency and had lasting effects on industry","The mechanical design of the Model T engine","Labor union strikes in the automobile industry"]', 1, 'The passage explains how the assembly line increased efficiency and describes its broader effects on manufacturing and labor.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-2', 'reading', 'p-assembly-line', 'reading_comprehension', 'According to the passage, how long did it take to build a car after the assembly line was introduced?', '["More than twelve hours","Roughly ninety minutes","Exactly one week","About thirty seconds"]', 1, 'The passage states the plant "reduced the time required to build a single car to roughly ninety minutes."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-3', 'reading', 'p-assembly-line', 'reading_comprehension', 'The word "monotony" in the passage is closest in meaning to', '["danger","repetitiveness","complexity","high pay"]', 1, '"Monotony of repetitive tasks" describes the repetitiveness of the work.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-4', 'reading', 'p-assembly-line', 'reading_comprehension', 'It can be inferred from the passage that Ford increased assembly line workers'' wages partly because', '["government regulations required it","repetitive tasks caused high worker turnover that higher wages helped reduce","the Model T''s price was increasing rapidly","skilled craftsmanship became more valuable"]', 1, 'The passage states wages rose "in part to reduce the high turnover caused by the monotony of repetitive tasks."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-5', 'reading', 'p-assembly-line', 'reading_comprehension', 'The word "it" in paragraph 3, in the phrase "it also drew criticism," refers to', '["the automobile industry generally","the assembly line","the Model T specifically","Henry Ford personally"]', 1, 'The sentence contrasts the assembly line''s efficiency gains with the criticism it also drew.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-assembly-line-6', 'reading', 'p-assembly-line', 'reading_comprehension', 'According to the passage, all of the following are mentioned as effects of the assembly line EXCEPT', '["a reduction in the time needed to build a car","lower prices for the Model T","criticism for reducing skilled work to repetitive tasks","the complete elimination of factory jobs"]', 3, 'The passage mentions faster build times, lower prices, and criticism of deskilled work; it does not mention the elimination of factory jobs.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-1', 'reading', 'p-permafrost', 'reading_comprehension', 'What is the passage mainly about?', '["The engineering challenges of building roads in the Arctic","How permafrost thaw releases greenhouse gases and creates a warming feedback loop","The history of climate change research in Siberia","The difference between carbon dioxide and methane"]', 1, 'The passage explains how thawing permafrost releases carbon dioxide and methane, creating a feedback loop that accelerates warming.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-2', 'reading', 'p-permafrost', 'reading_comprehension', 'According to the passage, why did organic material in permafrost not fully decompose?', '["It was buried too deep underground","Cold temperatures prevented the microorganisms responsible for decay from functioning","It lacked the nutrients needed for microbial activity","It was chemically preserved by high salt content"]', 1, 'The passage states decay was prevented because cold temperatures stopped decomposing microorganisms from functioning.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-3', 'reading', 'p-permafrost', 'reading_comprehension', 'The word "dormant" in the passage is closest in meaning to', '["inactive","toxic","abundant","fragile"]', 0, '"Long-dormant organic material" describes material that had been inactive/undecomposed for a long time.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-4', 'reading', 'p-permafrost', 'reading_comprehension', 'It can be inferred from the passage that permafrost thaw was not fully accounted for in earlier climate projections because', '["scientists did not believe the Arctic was warming","the carbon it released had previously been locked away and inaccessible","methane does not affect global temperatures","permafrost only exists in uninhabited regions"]', 1, 'The passage notes this newly released carbon "was previously locked away and not accounted for in earlier climate projections."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-5', 'reading', 'p-permafrost', 'reading_comprehension', 'The word "it" in paragraph 3, in the phrase "as it thaws," refers to', '["the atmosphere","the infrastructure","the permafrost/ground","the pipeline"]', 2, 'The sentence describes the ground beneath infrastructure thawing and subsiding.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-permafrost-6', 'reading', 'p-permafrost', 'reading_comprehension', 'According to the passage, all of the following are mentioned as being affected by permafrost thaw EXCEPT', '["buildings","roads","pipelines","ocean currents"]', 3, 'The passage names buildings, roads, and pipelines as infrastructure affected by thaw; ocean currents are not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-1', 'reading', 'p-hammurabi', 'reading_comprehension', 'What is the passage mainly about?', '["The military conquests of Hammurabi","The content, structure, and rediscovery of Hammurabi''s code of laws","The archaeology of ancient Iran","The daily life of Babylonian laborers"]', 1, 'The passage describes what the code contained, how it was structured, and how it was rediscovered in 1901.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-2', 'reading', 'p-hammurabi', 'reading_comprehension', 'According to the passage, how many individual laws does Hammurabi''s code contain?', '["6","100","282","1754"]', 2, 'The passage states the code "consists of 282 individual laws."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-3', 'reading', 'p-hammurabi', 'reading_comprehension', 'The word "proportional" in the passage is closest in meaning to', '["random","corresponding in degree","religious","unlimited"]', 1, '"Proportional retaliation" means a punishment corresponding in degree to the offense, as in "an eye for an eye."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-4', 'reading', 'p-hammurabi', 'reading_comprehension', 'It can be inferred from the passage that punishments under Hammurabi''s code were', '["identical regardless of social status","influenced by the social status of those involved","determined entirely by a jury","rarely enforced"]', 1, 'The passage states the prescribed punishment "often depended heavily on the social status of both the offender and the victim."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-5', 'reading', 'p-hammurabi', 'reading_comprehension', 'The word "Its" in paragraph 3, in the phrase "Its rediscovery," refers to', '["Babylon''s","Iran''s","the stele''s","France''s"]', 2, 'The sentence discusses the rediscovery of the stele bearing Hammurabi''s code.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-hammurabi-6', 'reading', 'p-hammurabi', 'reading_comprehension', 'According to the passage, all of the following topics are mentioned as being addressed by the code EXCEPT', '["property disputes","fixed wages for laborers","liability for construction defects","rules for religious worship"]', 3, 'The passage mentions property, family disputes, wages, and construction liability; religious worship rules are not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-1', 'reading', 'p-lichen', 'reading_comprehension', 'What is the passage mainly about?', '["The classification of fungi","The symbiotic relationship between fungi and photosynthetic partners that forms lichen","The chemical composition of gravestones","How lichens are used in cooking"]', 1, 'The passage explains how a fungus and a photosynthetic partner form the composite organism known as lichen.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-2', 'reading', 'p-lichen', 'reading_comprehension', 'According to the passage, what does the photosynthetic partner supply to the fungus?', '["Physical structure","Protection from sunlight","Carbohydrates produced through photosynthesis","Moisture retention"]', 2, 'The passage states the photosynthetic partner "supplies the fungus with the carbohydrates it cannot manufacture on its own."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-3', 'reading', 'p-lichen', 'reading_comprehension', 'The word "desiccation" in the passage is closest in meaning to', '["drying out","overheating","freezing","decay"]', 0, 'The fungus shields the photosynthetic partner from sunlight and desiccation, i.e., drying out.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-4', 'reading', 'p-lichen', 'reading_comprehension', 'It can be inferred from the passage that fungi cannot survive alone in the way lichen does because they', '["cannot retain moisture","lack chlorophyll and cannot photosynthesize their own food","are too small to be seen without a microscope","require animal hosts to reproduce"]', 1, 'The passage notes fungi "lack chlorophyll" and rely on the photosynthetic partner for carbohydrates.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-5', 'reading', 'p-lichen', 'reading_comprehension', 'The word "their" in paragraph 3, in the phrase "Their sensitivity to airborne pollutants," refers to', '["rocks","lichens","scientists","plants"]', 1, 'The paragraph discusses lichens'' sensitivity to pollutants as the basis for their use as air-quality indicators.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-lichen-6', 'reading', 'p-lichen', 'reading_comprehension', 'According to the passage, all of the following are mentioned as environments where lichen grow EXCEPT', '["tropical rainforests","bare Arctic rock","tree bark","ocean floors"]', 3, 'The passage names rainforests, Arctic rock, and tree bark as lichen habitats; ocean floors are not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-1', 'reading', 'p-vaccination', 'reading_comprehension', 'What is the passage mainly about?', '["The symptoms and history of smallpox outbreaks","How Edward Jenner developed and popularized vaccination against smallpox","The dangers of variolation as a medical practice","The global eradication of infectious diseases in general"]', 1, 'The passage traces Jenner''s experiment, the coining of the term "vaccination," and its eventual global adoption.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-2', 'reading', 'p-vaccination', 'reading_comprehension', 'According to the passage, what did rural folklore claim about milkmaids?', '["They were immune to all diseases","They rarely contracted smallpox after having cowpox","They discovered variolation","They refused all medical treatment"]', 1, 'The passage states folklore held that milkmaids who had cowpox "rarely contracted smallpox at all."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-3', 'reading', 'p-vaccination', 'reading_comprehension', 'The word "induce" in the passage is closest in meaning to', '["prevent","cause","diagnose","cure"]', 1, 'Variolation was meant to induce, i.e., cause, a milder case of the disease.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-4', 'reading', 'p-vaccination', 'reading_comprehension', 'It can be inferred from the passage that variolation was considered riskier than Jenner''s method because it', '["used material from cowpox rather than smallpox","exposed people to actual smallpox material, which could cause fatal infection","was performed only on children","required no medical training"]', 1, 'The passage states variolation used smallpox sore material and "sometimes caused fatal infections."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-5', 'reading', 'p-vaccination', 'reading_comprehension', 'The word "this" in paragraph 2, in the phrase "coined the term ''vaccination'' for this procedure," refers to', '["folk belief","variolation","the cowpox inoculation method Jenner tested","smallpox eradication"]', 2, '"This procedure" refers to the cowpox-based inoculation method Jenner had just performed on the boy.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-vaccination-6', 'reading', 'p-vaccination', 'reading_comprehension', 'According to the passage, all of the following are mentioned in connection with smallpox or its prevention EXCEPT', '["variolation","cowpox","Edward Jenner","antibiotics"]', 3, 'The passage discusses variolation, cowpox, and Jenner, but does not mention antibiotics, which do not treat viral disease.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-1', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'What is the passage mainly about?', '["The invention of steam power","How rapid industrial urbanization led to poor living conditions and eventual public health reform","The history of Manchester''s textile industry","The causes of cholera as a disease"]', 1, 'The passage traces industrial-era urban growth, the resulting overcrowding and disease, and the reforms that followed.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-2', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'According to the passage, how did Manchester''s population change between 1770 and the following decades?', '["It stayed roughly the same","It grew from about twenty-five thousand to several hundred thousand","It declined sharply","It doubled and then declined"]', 1, 'The passage states Manchester "grew from a modest market town of about twenty-five thousand people in 1770 to a city of several hundred thousand."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-3', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'The word "outpaced" in the passage is closest in meaning to', '["exceeded the speed of","financed","prevented","matched exactly"]', 0, 'Growth "outpaced" the government''s ability to provide services, meaning it exceeded that capacity''s speed.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-4', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'It can be inferred from the passage that cholera spread easily in industrial cities because', '["factories released toxic fumes into the air","many households shared contaminated water sources and sanitation facilities","workers refused to seek medical treatment","the cities were too sparsely populated"]', 1, 'The passage describes households sharing a single water source or latrine, creating ideal conditions for disease spread.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-5', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'The word "these" in paragraph 3, in the phrase "the severity of these outbreaks," refers to', '["factory closures","housing shortages","cholera outbreaks","political elections"]', 2, 'The previous paragraph describes cholera outbreaks sweeping through industrial cities.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-urbanization-6', 'reading', 'p-industrial-urbanization', 'reading_comprehension', 'According to the passage, all of the following are mentioned as results of industrial urbanization EXCEPT', '["overcrowded tenements","shared water sources and latrines","cholera outbreaks","declining factory employment"]', 3, 'The passage mentions overcrowded tenements, shared facilities, and cholera; declining factory employment is not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-1', 'reading', 'p-echolocation', 'reading_comprehension', 'What is the passage mainly about?', '["The diet of insect-eating bats","How bats use echolocation to navigate and hunt, and the adaptations that make it possible","The evolution of bat wings","How sonar technology was invented"]', 1, 'The passage explains the mechanism of echolocation and the physical adaptations that support it.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-2', 'reading', 'p-echolocation', 'reading_comprehension', 'According to the passage, what information can a bat determine from returning echoes?', '["Only the distance of an object","The distance, direction, size, shape, texture, and movement of an object","The exact species of its prey","The temperature of the surrounding air"]', 1, 'The passage states a bat can determine "distance and direction... size, shape, texture, and even whether it is moving."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-3', 'reading', 'p-echolocation', 'reading_comprehension', 'The word "faint" in the passage is closest in meaning to', '["loud","weak or hard to detect","delayed","artificial"]', 1, '"Faint returning echoes" are echoes that are weak and hard to detect compared to the bat''s own call.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-4', 'reading', 'p-echolocation', 'reading_comprehension', 'It can be inferred from the passage that without the middle-ear disconnection mechanism, bats would', '["be unable to fly","risk deafening themselves with their own calls","be unable to produce any sound","lose their sense of smell"]', 1, 'The passage explains this mechanism prevents the bat "from being deafened by its own call."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-5', 'reading', 'p-echolocation', 'reading_comprehension', 'The word "its" in paragraph 3, in the phrase "drawn on its underlying principles," refers to', '["sonar","echolocation","radar","darkness"]', 1, 'Engineers drew on the underlying principles of echolocation when developing sonar and radar.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-echolocation-6', 'reading', 'p-echolocation', 'reading_comprehension', 'According to the passage, all of the following are mentioned in connection with bat echolocation EXCEPT', '["specialized laryngeal muscles","large, mobile outer ears","a middle-ear disconnection mechanism","infrared vision"]', 3, 'The passage discusses laryngeal muscles, ear shape, and the middle-ear mechanism, but never mentions infrared vision.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-1', 'reading', 'p-panama-canal', 'reading_comprehension', 'What is the passage mainly about?', '["The geography of the Isthmus of Panama","The failed French attempt and successful American completion of the Panama Canal","The biography of Ferdinand de Lesseps","The construction of the Suez Canal"]', 1, 'The passage contrasts the failed French effort with the successful American completion using a lock-based design and disease control.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-2', 'reading', 'p-panama-canal', 'reading_comprehension', 'According to the passage, why did the French project ultimately fail?', '["A lack of interest from investors","Financial mismanagement, difficult terrain, and disease","Opposition from the Panamanian government","A shortage of construction materials"]', 1, 'The passage states the project was "defeated by a combination of financial mismanagement, unstable mountainous terrain, and... disease."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-3', 'reading', 'p-panama-canal', 'reading_comprehension', 'The word "devastatingly" in the passage is closest in meaning to', '["surprisingly","mildly","destructively","slowly"]', 2, 'Disease is described as the most devastating, i.e., most destructive, cause of the French project''s failure.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-4', 'reading', 'p-panama-canal', 'reading_comprehension', 'It can be inferred from the passage that the French were unable to control yellow fever and malaria mainly because', '["they had no doctors on site","the link between mosquitoes and disease transmission was not yet known","mosquitoes did not exist in Panama in the 1880s","yellow fever had not yet been identified as a disease"]', 1, 'The passage states the mosquito-disease connection "was not yet understood" during the French attempt, which explains why they could not control the outbreaks.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-5', 'reading', 'p-panama-canal', 'reading_comprehension', 'The word "This approach" in paragraph 2 refers to', '["the sea-level canal design","the lock-based system","the Suez Canal method","Gorgas''s mosquito control campaign"]', 1, 'The sentence follows the description of the lock-based system that made use of Gatun Lake.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-panama-6', 'reading', 'p-panama-canal', 'reading_comprehension', 'According to the passage, all of the following are mentioned as factors in the canal''s completion EXCEPT', '["the lock-based system","Gatun Lake","mosquito control efforts","the invention of dynamite"]', 3, 'The passage discusses the lock system, Gatun Lake, and Gorgas''s mosquito control; dynamite is not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-1', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'What is the passage mainly about?', '["The biography of Leon Festinger","Cognitive dissonance theory and how people resolve contradictory beliefs","A specific religious group''s beliefs about the end of the world","Modern marketing techniques"]', 1, 'The passage introduces cognitive dissonance theory and describes strategies people use to resolve conflicting beliefs.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-2', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'According to the passage, how did some group members react when the predicted end of the world did not occur?', '["They abandoned their belief immediately","They reinterpreted the failed prediction as evidence their faith had saved the world","They demanded a refund from the group''s leader","They stopped discussing the prediction entirely"]', 1, 'The passage states members "reinterpreted the failed prophecy as evidence that their faith had saved the world."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-3', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'The word "motivating" in the passage is closest in meaning to', '["confusing","driving someone to act","irrelevant","forgettable"]', 1, 'Festinger argued dissonance is "actively motivating," driving people to reduce the inconsistency.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-4', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'It can be inferred from the passage that cognitive dissonance theory can help explain why people', '["always change their beliefs when faced with contradictory evidence","sometimes continue investing in a failing project rather than admit a past mistake","never make decisions under uncertainty","prefer to work in groups rather than alone"]', 1, 'The passage states the theory explains continued investment in a failing project to avoid admitting an earlier mistake.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-5', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'The word "It" in paragraph 3, in the phrase "It helps explain why people often rate a decision more favorably," refers to', '["the failed prophecy","cognitive dissonance theory","the small group","Leon Festinger"]', 1, 'The paragraph opens by stating cognitive dissonance theory has been applied broadly, and "It" continues that reference.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-dissonance-6', 'reading', 'p-cognitive-dissonance', 'reading_comprehension', 'According to the passage, all of the following are mentioned as strategies for resolving cognitive dissonance EXCEPT', '["adding new justifying beliefs","changing one''s behavior to match a belief","minimizing the perceived importance of the inconsistency","seeking therapy from a psychologist"]', 3, 'The passage names adding justifying beliefs, changing behavior, and minimizing importance as strategies; therapy is not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-1', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'What is the passage mainly about?', '["The causes of low rainfall in desert regions","How desert plants and animals have adapted to water scarcity and temperature extremes","The life cycle of the cactus","The behavior of nocturnal predators"]', 1, 'The passage surveys plant and animal adaptations that address desert water scarcity and temperature swings.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-2', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'According to the passage, how do many desert plants reduce water loss through their leaves?', '["By growing extremely large leaves","By having small, needle-like leaves or spines instead of broad leaves","By shedding all their leaves permanently","By growing only underground"]', 1, 'The passage states many desert plants have "small, needle-like leaves or spines" rather than broad, water-losing leaves.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-3', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'The word "transpiration" in the passage is closest in meaning to', '["photosynthesis","the loss of water vapor from plant surfaces","the absorption of sunlight","root growth"]', 1, 'Broad leaves "lose water rapidly through transpiration," i.e., water vapor loss from plant surfaces.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-4', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'It can be inferred from the passage that opening pores only at night helps desert plants because', '["sunlight is not needed for photosynthesis at all","nighttime temperatures are lower, reducing water lost through the open pores","nocturnal animals pollinate the plants","carbon dioxide is more abundant at night"]', 1, 'The passage explains pores open at night "when temperatures are lower and less water is lost."', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-5', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'The word "they" in paragraph 3, in the phrase "they can survive largely on water produced internally," refers to', '["desert plants","nocturnal predators","kangaroo rats (or similarly adapted species)","underground burrows"]', 2, 'The sentence describes kangaroo rats surviving on internally produced water from digesting dry seeds.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id, section_slug, passage_id, question_type, stem, choices, correct_index, explanation, difficulty, status) VALUES ('q-read-desert-6', 'reading', 'p-desert-adaptations', 'reading_comprehension', 'According to the passage, all of the following are mentioned as desert animal or plant adaptations EXCEPT', '["nocturnal behavior","water storage in thickened stems","highly efficient kidneys","migration to wetter climates during droughts"]', 3, 'The passage mentions nocturnal behavior, succulent water storage, and efficient kidneys; migration is not mentioned.', 'medium', 'published') ON CONFLICT(id) DO NOTHING;
